/*
 * A349757  Even numbers that are both the sum of a twin prime pair and the
 *          sum of 1 and a prime.
 * https://oeis.org/A349757
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 5, u16 n <= 46, u32 n <= 46, u64 n <= 46, u128 n <= 46,
 *            big any n
 * Helpers:   build_primes, is_prime, is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  A349757: even numbers that are both the sum of a twin prime pair and
 *  the sum of 1 and a prime.  The sequence is generated by scanning the
 *  primes p such that p, p+2 and 2p+1 are all prime; then a term is
 *  2(p+1).  No lookup table is used.  */
#include <stddef.h>
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/is_prime.h"
#include "../utils/is_prime_big.h"
#include "../utils/build_primes.h"

/* ---------- mutable global state ---------- */
static idx_t prime_limit = 0;            /* upper bound of built primes   */
static idx_t *primes = NULL;             /* array of primes                */
static size_t primes_len = 0;            /* number of primes in array      */
static size_t next_prime_idx = 0;        /* next prime to examine          */

static seq_t *seq_cache = NULL;          /* generated sequence values      */
static size_t seq_len = 0;               /* number of cached terms         */
static size_t seq_cap = 0;               /* capacity of cache array        */

/* ---------- helper routines ---------- */

/* Rebuild the primes array up to 'limit'.  Frees any existing array. */
static void ensure_prime_limit(idx_t limit)
{
    if (limit <= prime_limit)
        return;

    idx_t *new_primes = NULL;
    size_t new_count = 0;
    build_primes(limit, &new_primes, &new_count);  /* builds primes <= limit */
    free(primes);
    primes = new_primes;
    primes_len = new_count;
    prime_limit = limit;
}

/* Grow the cache array to accommodate at least 'need' elements. */
static void grow_cache(size_t need)
{
    if (need <= seq_cap)
        return;
    size_t new_cap = seq_cap ? seq_cap << 1 : 64;
    while (new_cap < need)
        new_cap <<= 1;
    seq_t *tmp = (seq_t *)realloc(seq_cache, new_cap * sizeof(seq_t));
    if (!tmp)
        abort();
    seq_cache = tmp;
    seq_cap = new_cap;
}

/* Generate sequence terms until at least 'n' terms are cached.  */
static void compute_terms_up_to(idx_t n)
{
    if (n == 0 || seq_len >= n)
        return;

    /* Start with a modest prime limit; will grow as needed. */
    if (prime_limit == 0)
        ensure_prime_limit(1000);

    while (seq_len < n) {
        /* If we have exhausted the current prime list, extend it. */
        if (next_prime_idx >= primes_len) {
            idx_t new_limit = prime_limit * 2;
            if (new_limit <= prime_limit)        /* protect against overflow */
                new_limit = prime_limit + 1000;
            ensure_prime_limit(new_limit);
            continue;                            /* retry with larger list */
        }

        idx_t p = primes[next_prime_idx++];
        /* twin prime test: check p+2 is prime */
        if (!is_prime(p + 2))
            continue;

        /* 2p+1 prime test using big‑integer primality routine */
        seq_t candidate = (seq_t) p * 2 + 2;        /* 2(p+1)   */
        seq_t two_p_plus_one = candidate - 1;      /* 2p+1     */
        if (!is_prime_big(two_p_plus_one))
            continue;

        /* found a valid term */
        grow_cache(seq_len + 1);
        seq_cache[seq_len++] = candidate;
    }
}

/* ---------- required function ---------- */
seq_t a(idx_t n)
{
    if (n == 0)
        return 0;
    compute_terms_up_to(n);
    return seq_cache[n - 1];
}
